__syncthreads();

if (warp == 0) {
  sum_sq = lane < warps ? shared[lane] : 0.0f;
#pragma unroll
  for (uint32_t offset = kWarp / 2; offset > 0; offset /= 2) {
    sum_sq += shared_xor(sum_sq, offset, shared + kReduction);
  }
  shared[0] = sum_sq;
}
__syncthreads();

const float mean_square = shared[0] / float(width) + epsilon;
