// Fused residual add + LayerNorm over the last (hidden) axis.
//
//   added  = fp16(x + residual)                 -> materialized (needed later)
//   output = fp16((added - mean) * rsqrt(var + eps) * gamma + beta)
//
// Statistics are taken on the *rounded* fp16 values, matching the reference.
// The op is bandwidth bound: six tensors of B*S*H halves move through memory.
// Every variant keeps the row in registers between the two reduction phases
// and moves data with 16-byte accesses.

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <cstdlib>

namespace {

constexpr int kThreads = 128;              // four warps
constexpr int kVec = 8;                    // fp16 lanes per 16-byte access
constexpr int kWarps = kThreads / 32;
constexpr int kGroup = kThreads * kVec;    // columns per row in one sweep
constexpr int kLanes = 32;
constexpr int kRounds = kGroup / (kLanes * kVec);
constexpr int kFallbackThreads = 256;
constexpr float kEpsilon = 1e-12f;
constexpr unsigned kFullMask = 0xffffffffu;

__device__ __forceinline__ float warp_sum(float value) {
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1)
    value += __shfl_xor_sync(kFullMask, value, offset);
  return value;
}

// CTA-wide sum: warp butterflies, one shared round, broadcast to every thread.
__device__ __forceinline__ float block_sum(float value, float* scratch) {
  const int lane = threadIdx.x & 31;
  const int warp = threadIdx.x >> 5;
  value = warp_sum(value);
  if (lane == 0) scratch[warp] = value;
  __syncthreads();
  if (warp == 0) {
    value = lane < kWarps ? scratch[lane] : 0.0f;
    value = warp_sum(value);
    if (lane == 0) scratch[0] = value;
  }
  __syncthreads();
  return scratch[0];
}

// Two rows per CTA: both sums reduce in the same shared round.
__device__ __forceinline__ float2 block_sum2(float2 value, float* scratch) {
  const int lane = threadIdx.x & 31;
  const int warp = threadIdx.x >> 5;
  value.x = warp_sum(value.x);
  value.y = warp_sum(value.y);
  if (lane == 0) {
    scratch[warp] = value.x;
    scratch[kWarps + warp] = value.y;
  }
  __syncthreads();
  if (warp == 0) {
    value.x = lane < kWarps ? scratch[lane] : 0.0f;
    value.y = lane < kWarps ? scratch[kWarps + lane] : 0.0f;
    value.x = warp_sum(value.x);
    value.y = warp_sum(value.y);
    if (lane == 0) {
      scratch[0] = value.x;
      scratch[1] = value.y;
    }
  }
  __syncthreads();
  return make_float2(scratch[0], scratch[1]);
}

template <bool kStream>
__device__ __forceinline__ uint4 load16(const uint4* address) {
  return kStream ? __ldcs(address) : *address;
}

template <bool kStream>
__device__ __forceinline__ void store16(uint4* address, uint4 value) {
  if (kStream) {
    __stcs(address, value);
  } else {
    *address = value;
  }
}

// Rounded residual sum of one 16-byte group, fp32 accumulation.
template <bool kStream>
__device__ __forceinline__ void add_group(const __half* x, const __half* residual,
                                          __half* added, int64_t offset,
                                          float* values, float* sum) {
  const uint4 x_pack = load16<kStream>(reinterpret_cast<const uint4*>(x + offset));
  const uint4 r_pack =
      load16<kStream>(reinterpret_cast<const uint4*>(residual + offset));
  const __half* x_vals = reinterpret_cast<const __half*>(&x_pack);
  const __half* r_vals = reinterpret_cast<const __half*>(&r_pack);

  __half rounded[kVec];
  #pragma unroll
  for (int j = 0; j < kVec; ++j) {
    values[j] = __half2float(__float2half_rn(__half2float(x_vals[j]) +
                                             __half2float(r_vals[j])));
    rounded[j] = __float2half_rn(values[j]);
    *sum += values[j];
  }
  store16<kStream>(reinterpret_cast<uint4*>(added + offset),
                   *reinterpret_cast<const uint4*>(rounded));
}

// Affine normalization of one 16-byte group from the cached row.
template <bool kStream>
__device__ __forceinline__ void store_group(const float* values, const float mean,
                                            float inverse, const __half* gamma,
                                            const __half* beta, __half* output,
                                            int64_t offset) {
  const uint4 g_pack = load16<kStream>(reinterpret_cast<const uint4*>(gamma + offset % kGroup));
  const uint4 b_pack = load16<kStream>(reinterpret_cast<const uint4*>(beta + offset % kGroup));
  const __half* g_vals = reinterpret_cast<const __half*>(&g_pack);
  const __half* b_vals = reinterpret_cast<const __half*>(&b_pack);

  __half result[kVec];
  #pragma unroll
  for (int j = 0; j < kVec; ++j) {
    const float scaled = (values[j] - mean) * inverse;
    result[j] = __float2half_rn(
        fmaf(scaled, __half2float(g_vals[j]), __half2float(b_vals[j])));
  }
  store16<kStream>(reinterpret_cast<uint4*>(output + offset),
                   *reinterpret_cast<const uint4*>(result));
}

// Variant A: hidden == kGroup, one CTA per row, whole row in registers.
template <bool kStream>
__global__ __launch_bounds__(kThreads) void norm_vector_kernel(
    const __half* __restrict__ x, const __half* __restrict__ residual,
    const __half* __restrict__ gamma, const __half* __restrict__ beta,
    __half* __restrict__ output, __half* __restrict__ added, int hidden) {
  __shared__ float scratch[kWarps];

  const int64_t offset = static_cast<int64_t>(blockIdx.x) * hidden + threadIdx.x * kVec;
  float values[kVec];
  float sum = 0.0f;
  add_group<kStream>(x, residual, added, offset, values, &sum);

  const float mean = block_sum(sum, scratch) * (1.0f / hidden);
  float square_sum = 0.0f;
  #pragma unroll
  for (int j = 0; j < kVec; ++j) {
    const float centered = values[j] - mean;
    square_sum = fmaf(centered, centered, square_sum);
  }
  const float inverse =
      rsqrtf(block_sum(square_sum, scratch) * (1.0f / hidden) + kEpsilon);

  store_group<kStream>(values, mean, inverse, gamma, beta, output, offset);
}

// Variant B: two rows per CTA, shared reduction rounds, doubled load stream.
template <bool kStream>
__global__ __launch_bounds__(kThreads) void norm_dual_kernel(
    const __half* __restrict__ x, const __half* __restrict__ residual,
    const __half* __restrict__ gamma, const __half* __restrict__ beta,
    __half* __restrict__ output, __half* __restrict__ added, int hidden) {
  __shared__ float scratch[2 * kWarps];

  const int64_t row = static_cast<int64_t>(blockIdx.x) * 2;
  const int64_t offset_a = row * hidden + threadIdx.x * kVec;
  const int64_t offset_b = offset_a + hidden;

  float values_a[kVec];
  float values_b[kVec];
  float sum_a = 0.0f;
  float sum_b = 0.0f;
  add_group<kStream>(x, residual, added, offset_a, values_a, &sum_a);
  add_group<kStream>(x, residual, added, offset_b, values_b, &sum_b);

  const float2 sums = block_sum2(make_float2(sum_a, sum_b), scratch);
  const float mean_a = sums.x * (1.0f / hidden);
  const float mean_b = sums.y * (1.0f / hidden);

  float square_a = 0.0f;
  float square_b = 0.0f;
  #pragma unroll
  for (int j = 0; j < kVec; ++j) {
    const float centered_a = values_a[j] - mean_a;
    const float centered_b = values_b[j] - mean_b;
    square_a = fmaf(centered_a, centered_a, square_a);
    square_b = fmaf(centered_b, centered_b, square_b);
  }
  const float2 squares = block_sum2(make_float2(square_a, square_b), scratch);
  const float scale = 1.0f / hidden;
  const float inverse_a = rsqrtf(squares.x * scale + kEpsilon);
  const float inverse_b = rsqrtf(squares.y * scale + kEpsilon);

  store_group<kStream>(values_a, mean_a, inverse_a, gamma, beta, output, offset_a);
  store_group<kStream>(values_b, mean_b, inverse_b, gamma, beta, output, offset_b);
}

// Variant C: one warp per row, shuffle-only reduction, no CTA barrier.
template <bool kStream>
__global__ __launch_bounds__(kThreads) void norm_warp_kernel(
    const __half* __restrict__ x, const __half* __restrict__ residual,
    const __half* __restrict__ gamma, const __half* __restrict__ beta,
    __half* __restrict__ output, __half* __restrict__ added, int hidden) {
  const int lane = threadIdx.x & 31;
  const int64_t row = static_cast<int64_t>(blockIdx.x) * kWarps + (threadIdx.x >> 5);
  const int64_t base = row * hidden;

  uint4 x_pack[kRounds];
  uint4 r_pack[kRounds];
  #pragma unroll
  for (int r = 0; r < kRounds; ++r) {
    const int64_t offset = base + r * (kLanes * kVec) + lane * kVec;
    x_pack[r] = load16<kStream>(reinterpret_cast<const uint4*>(x + offset));
    r_pack[r] = load16<kStream>(reinterpret_cast<const uint4*>(residual + offset));
  }

  float values[kRounds * kVec];
  float sum = 0.0f;
  #pragma unroll
  for (int r = 0; r < kRounds; ++r) {
    const __half* x_vals = reinterpret_cast<const __half*>(&x_pack[r]);
    const __half* r_vals = reinterpret_cast<const __half*>(&r_pack[r]);
    __half rounded[kVec];
    #pragma unroll
    for (int j = 0; j < kVec; ++j) {
      float* value = &values[r * kVec + j];
      *value = __half2float(__float2half_rn(__half2float(x_vals[j]) +
                                            __half2float(r_vals[j])));
      rounded[j] = __float2half_rn(*value);
      sum += *value;
    }
    const int64_t offset = base + r * (kLanes * kVec) + lane * kVec;
    store16<kStream>(reinterpret_cast<uint4*>(added + offset),
                     *reinterpret_cast<const uint4*>(rounded));
  }

  const float mean = warp_sum(sum) * (1.0f / hidden);
  float square_sum = 0.0f;
  #pragma unroll
  for (int r = 0; r < kRounds; ++r) {
    #pragma unroll
    for (int j = 0; j < kVec; ++j) {
      const float centered = values[r * kVec + j] - mean;
      square_sum = fmaf(centered, centered, square_sum);
    }
  }
  const float inverse = rsqrtf(warp_sum(square_sum) * (1.0f / hidden) + kEpsilon);

  #pragma unroll
  for (int r = 0; r < kRounds; ++r) {
    const int column = r * (kLanes * kVec) + lane * kVec;
    store_group<kStream>(&values[r * kVec], mean, inverse, gamma, beta, output,
                         base + column - base + column);
  }
}

// Generic path: any hidden width, one CTA per row, three streaming passes.
__global__ __launch_bounds__(kFallbackThreads) void norm_scalar_kernel(
    const __half* __restrict__ x, const __half* __restrict__ residual,
    const __half* __restrict__ gamma, const __half* __restrict__ beta,
    __half* __restrict__ output, __half* __restrict__ added, int64_t rows,
    int hidden) {
  __shared__ float scratch[kFallbackThreads / 32];

  const int64_t row = blockIdx.x;
  if (row >= rows) return;
  const int64_t base = row * hidden;

  float sum = 0.0f;
  for (int col = threadIdx.x; col < hidden; col += kFallbackThreads) {
    const float value = __half2float(__float2half_rn(
        __half2float(x[base + col]) + __half2float(residual[base + col])));
    added[base + col] = __float2half_rn(value);
    sum += value;
  }
  const float mean = block_sum(sum, scratch) * (1.0f / hidden);

  float square_sum = 0.0f;
  for (int col = threadIdx.x; col < hidden; col += kFallbackThreads) {
    const float centered = __half2float(added[base + col]) - mean;
    square_sum = fmaf(centered, centered, square_sum);
  }
  const float inverse =
      rsqrtf(block_sum(square_sum, scratch) * (1.0f / hidden) + kEpsilon);

  for (int col = threadIdx.x; col < hidden; col += kFallbackThreads) {
    const float scaled = (__half2float(added[base + col]) - mean) * inverse;
    output[base + col] = __float2half_rn(
        fmaf(scaled, __half2float(gamma[col]), __half2float(beta[col])));
  }
}

void check_row_tensor(const torch::Tensor& tensor, int64_t rows, int hidden) {
  TORCH_CHECK(tensor.is_cuda(), \"expected CUDA tensor\");
  TORCH_CHECK(tensor.scalar_type() == torch::kFloat16, \"expected float16\");
  TORCH_CHECK(tensor.dim() == 3, \"expected rank 3\");
  TORCH_CHECK(tensor.is_contiguous(), \"expected contiguous tensor\");
  TORCH_CHECK(tensor.size(0) * tensor.size(1) == rows, \"row count mismatch\");
  TORCH_CHECK(tensor.size(2) == hidden, \"hidden size mismatch\");
}

void check_vector(const torch::Tensor& tensor, int64_t hidden) {
  TORCH_CHECK(tensor.is_cuda(), \"expected CUDA tensor\");
  TORCH_CHECK(tensor.scalar_type() == torch::kFloat16, \"expected float16\");
  TORCH_CHECK(tensor.dim() == 1, \"expected rank 1\");
  TORCH_CHECK(tensor.is_contiguous(), \"expected contiguous tensor\");
  TORCH_CHECK(tensor.size(0) == hidden, \"hidden size mismatch\");
}

int selected_variant() {
  const char* text = std::getenv(\"RLN_VARIANT\");
  return text == nullptr ? 0 : std::atoi(text);
}

void kernel(const torch::Tensor& x, const torch::Tensor& residual,
            const torch::Tensor& gamma, const torch::Tensor& beta,
            const torch::Tensor& output, const torch::Tensor& added) {
  const int64_t rows = x.size(0) * x.size(1);
  const int64_t hidden = x.size(2);
  check_row_tensor(x, rows, hidden);
  check_row_tensor(residual, rows, hidden);
  check_row_tensor(output, rows, hidden);
  check_row_tensor(added, rows, hidden);
  check_vector(gamma, hidden);
  check_vector(beta, hidden);
  TORCH_CHECK(x.device() == residual.device() && x.device() == output.device() &&
                  x.device() == added.device(),
              \"device mismatch\");
  if (rows == 0 || hidden == 0) return;

  c10::cuda::CUDAGuard guard(x.device());
  const cudaStream_t stream =
      c10::cuda::getCurrentCUDAStream(x.get_device()).stream();

  const __half* x_ptr = reinterpret_cast<const __half*>(x.data_ptr<at::Half>());
  const __half* residual_ptr =
      reinterpret_cast<const __half*>(residual.data_ptr<at::Half>());
  const __half* gamma_ptr =
      reinterpret_cast<const __half*>(gamma.data_ptr<at::Half>());
  const __half* beta_ptr = reinterpret_cast<const __half*>(beta.data_ptr<at::Half>());
  __half* output_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());
  __half* added_ptr = reinterpret_cast<__half*>(added.data_ptr<at::Half>());
  const int width = static_cast<int>(hidden);
  const int variant = selected_variant();

  if (hidden "'!= kGroup) {
    norm_scalar_kernel<<<static_cast<unsigned>(rows), kFallbackThreads, 0, stream>>>(
        x_ptr, residual_ptr, gamma_ptr, beta_ptr, output_ptr, added_ptr, rows, width);
  } else if (variant == 1 || variant == 3) {
    const bool warp_variant = variant == 3;
    if (warp_variant) {
      norm_warp_kernel<true><<<static_cast<unsigned>(rows / kWarps), kThreads, 0, stream>>>(
          x_ptr, residual_ptr, gamma_ptr, beta_ptr, output_ptr, added_ptr, width);
    } else {
      norm_vector_kernel<true><<<static_cast<unsigned>(rows), kThreads, 0, stream>>>(
          x_ptr, residual_ptr, gamma_ptr, beta_ptr, output_ptr, added_ptr, width);
    }
  } else if (variant == 2) {
    norm_dual_kernel<false><<<static_cast<unsigned>(rows / 2), kThreads, 0, stream>>>(
        x_ptr, residual_ptr, gamma_ptr, beta_ptr, output_ptr, added_ptr, width);
  } else if (variant == 4) {
    norm_dual_kernel<true><<<static_cast<unsigned>(rows / 2), kThreads, 0, stream>>>(
        x_ptr, residual_ptr, gamma_ptr, beta_ptr, output_ptr, added_ptr, width);
  } else {
    norm_vector_kernel<false><<<static_cast<unsigned>(rows), kThreads, 0, stream>>>(
        x_ptr, residual_ptr, gamma_ptr, beta_ptr, output_ptr, added_ptr, width);
  }
  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, cudaGetErrorString(error));
}
}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("kernel", &kernel);
}
